import { Component, h, Prop, EventEmitter, Event } from '@stencil/core';

@Component({
  tag: 'std-button',
  styleUrl: 'std-button.css',
  shadow: true
})
export class StdButtonComponent {
  @Prop() label: string;
  @Prop() icon: string;
  @Prop() iconPosition = 'right';
  @Prop() type = 'primary';
  @Prop() size = 'l';
  @Prop() href: string;
  @Prop() disabled: boolean;
  @Prop() img: boolean;
  @Prop() srcImage: string;
  @Prop() classes: string;
  @Prop() iconClasses: string;
  @Prop() imageClasses: string;

  @Prop() loading: boolean;

  @Event() clickEvent: EventEmitter;
  @Event() focusEvent: EventEmitter;
  @Event() blurEvent: EventEmitter;

  onClick(event: Event) {
    event.preventDefault();
    this.clickEvent.emit(event);
  }

  render() {
    const defaultClasses = 'inline-flex justify-center items-center font-bold rounded-full transition-all duration-300 ease-in-out';

    const typeClasses = {
      primary: 'w-full bg-primary text-white hover:bg-primary-dark',
      secondary: 'w-full bg-white text-primary shadow-button hover:bg-button-secondary-hover hover:text-primary-dark',
      tertiary: 'w-full bg-dark/0 text-alternative hover:bg-dark/[0.04] hover:text-alternative-dark '
    }[this.type];

    const sizeClasses = {
      s: 'gap-1 min-w-28 text-sm px-4 py-1.5',
      l: 'gap-1 min-w-36 px-5 py-3'
    }[this.size];

    const disabledClasses = {
      primary: 'disabled:bg-dark/[0.06] disabled:text-dark/[0.23] disabled:shadow-none',
      secondary: 'disabled:bg-dark/[0.06] disabled:text-dark/[0.23] disabled:shadow-none',
      tertiary: 'disabled:bg-dark/0 disabled:text-dark/[0.23] disabled:shadow-none'
    }[this.type];

    const buttonClasses = [
      defaultClasses,
      this.href && this.disabled ? 'bg-dark/[0.06] text-dark/[0.23] shadow-none pointer-events-none' : typeClasses,
      sizeClasses,
      this.disabled && !this.href ? disabledClasses : '',
      this.classes
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    const iconClass = [`text-xl leading-none icon-${this.icon}`, this.iconClasses].join(' ').trim().replace(/\s+/g, ' ');

    return this.href ? (
      <a class={buttonClasses} href={this.href} aria-label={this.label}>
        {this.icon && this.iconPosition === 'left' && <i class={iconClass} />}
        {this.label && <span>{this.label}</span>}
        {this.icon && this.iconPosition === 'right' && <i class={iconClass} />}
      </a>
    ) : (
      <button
        class={buttonClasses}
        disabled={this.disabled}
        aria-label={this.label}
        onFocus={e => this.focusEvent.emit(e)}
        onBlur={e => this.blurEvent.emit(e)}
        onClick={e => this.onClick(e)}>
        {this.icon && this.iconPosition === 'left' && <i class={iconClass} />}
        {this.label && <span>{this.label}</span>}
        {this.icon && this.iconPosition === 'right' && <i class={iconClass} />}
        {this.loading && (
          <svg class="animate-svg" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
        )}
        {this.img && <std-image src={this.srcImage} image-classes={this.imageClasses}></std-image>}
      </button>
    );
  }
}
